macro_rules! should_reborrow_from_env_of_parent_coroutine_closure {
    () => {
        # [doc = " Determines whether a child capture that is derived from a parent capture"] # [doc = " should be borrowed with the lifetime of the parent coroutine-closure's env."] # [doc = ""] # [doc = " There are two cases when this needs to happen:"] # [doc = ""] # [doc = " (1.) Are we borrowing data owned by the parent closure? We can determine if"] # [doc = " that is the case by checking if the parent capture is by move, EXCEPT if we"] # [doc = " apply a deref projection of an immutable reference, reborrows of immutable"] # [doc = " references which aren't restricted to the LUB of the lifetimes of the deref"] # [doc = " chain. This is why `&'short mut &'long T` can be reborrowed as `&'long T`."] # [doc = ""] # [doc = " ```rust"] # [doc = " let x = &1i32; // Let's call this lifetime `'1`."] # [doc = " let c = async move || {"] # [doc = "     println!(\"{:?}\", *x);"] # [doc = "     // Even though the inner coroutine borrows by ref, we're only capturing `*x`,"] # [doc = "     // not `x`, so the inner closure is allowed to reborrow the data for `'1`."] # [doc = " };"] # [doc = " ```"] # [doc = ""] # [doc = " (2.) If a coroutine is mutably borrowing from a parent capture, then that"] # [doc = " mutable borrow cannot live for longer than either the parent *or* the borrow"] # [doc = " that we have on the original upvar. Therefore we always need to borrow the"] # [doc = " child capture with the lifetime of the parent coroutine-closure's env."] # [doc = ""] # [doc = " ```rust"] # [doc = " let mut x = 1i32;"] # [doc = " let c = async || {"] # [doc = "     x = 1;"] # [doc = "     // The parent borrows `x` for some `&'1 mut i32`."] # [doc = "     // However, when we call `c()`, we implicitly autoref for the signature of"] # [doc = "     // `AsyncFnMut::async_call_mut`. Let's call that lifetime `'call`. Since"] # [doc = "     // the maximum that `&'call mut &'1 mut i32` can be reborrowed is `&'call mut i32`,"] # [doc = "     // the inner coroutine should capture w/ the lifetime of the coroutine-closure."] # [doc = " };"] # [doc = " ```"] # [doc = ""] # [doc = " If either of these cases apply, then we should capture the borrow with the"] # [doc = " lifetime of the parent coroutine-closure's env. Luckily, if this function is"] # [doc = " not correct, then the program is not unsound, since we still borrowck and validate"] # [doc = " the choices made from this function -- the only side-effect is that the user"] # [doc = " may receive unnecessary borrowck errors."] fn should_reborrow_from_env_of_parent_coroutine_closure < 'tcx > (parent_capture : & ty :: CapturedPlace < 'tcx > , child_capture : & ty :: CapturedPlace < 'tcx > ,) -> bool { (! parent_capture . is_by_ref () && ! child_capture . place . projections . iter () . enumerate () . skip (parent_capture . place . projections . len ()) . any (| (idx , proj) | { matches ! (proj . kind , ProjectionKind :: Deref) && matches ! (child_capture . place . ty_before_projection (idx) . kind () , ty :: Ref (.., ty :: Mutability :: Not)) })) || matches ! (child_capture . info . capture_kind , UpvarCapture :: ByRef (ty :: BorrowKind :: Mutable)) }
    };
}

should_reborrow_from_env_of_parent_coroutine_closure!()